const lessons=[['Prompting That Gets Results','Turn vague requests into clear instructions with a goal, context, constraints, and an output format.','Practice: turn “Make me a study plan” into a precise brief for your own learning goals.'],['Context Is the Superpower','Give AI the relevant background and reference material it needs to produce a useful answer.','Practice: build a short context pack for a task you do regularly.'],['Iterative Prompting','Improve a first draft with focused feedback and a repeatable conversation loop.','Practice: review an answer, identify what is missing, and write a targeted follow-up.'],['Research, Fact-Checking & Verification','Use AI to support research while keeping evidence and verification in the process.','Practice: identify claims that need checking and plan how to verify them.'],['Create Better with AI','Explore ideas, drafts, and variations while keeping your own direction and judgment.','Practice: create three different approaches to a brief and explain your preferred choice.'],['AI + Coding','Use AI as a tutor, debugging partner, and pair programmer while building understanding.','Practice: ask for an explanation and a testable change rather than copying code blindly.'],['Build Your Personal AI Workflow','Combine prompting, context, iteration, and verification into a process you can reuse.','Practice: map one recurring task from the initial brief to a checked, useful result.']];
document.querySelector('#lessons').innerHTML=lessons.map((l,i)=>`<details class="lesson"><summary><span class="lesson-number">0${i+1}</span><span>${l[0]}</span><span class="plus" aria-hidden="true">+</span></summary><div class="lesson-body"><p>${l[1]}</p><p class="practice">${l[2]}</p></div></details>`).join('');
const examples={study:['Make me a study plan.','Create a 7-day biology revision plan for a student who has 45 minutes each evening. Focus on cells and genetics. Include active recall and a short daily quiz. Return a table with the day, topic, activity, and time.'],writing:['Write a post about AI.','Draft a 150-word introductory post about using AI to study. Write for university students in a friendly, practical tone. Include two examples, avoid hype, and end with one action readers can try today.'],coding:['Fix my code.','Help me debug this function. Ask for the code, expected behavior, and exact error first. Then explain the likely cause, propose the smallest change, and suggest a test that checks the fix.']};
let selected='study';function renderExample(){document.querySelector('#weak').textContent=examples[selected][0];document.querySelector('#strong').textContent=examples[selected][1];document.querySelector('#copy-status').textContent='';document.querySelectorAll('[data-example]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.example===selected)));}document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.example;renderExample();}));document.querySelector('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(examples[selected][1]);document.querySelector('#copy-status').textContent='Copied!';}catch{document.querySelector('#copy-status').textContent='Select the prompt text above to copy it.';}});renderExample();
